from typing import Literal

def quartile_sort_position(name: str) -> Literal[
    "before_25",
    "between_25_50",
    "between_50_75",
    "after_75"
]:

    # Normalize the name for consistent alphabetical comparison.
    normalized_name = name.strip().title()

    # Quartile boundaries (only the three names given).
    q25 = "Clark"
    q50 = "Gonzalez"
    q75 = "Lewis"

    # Lexicographic comparison.
    if normalized_name < q25:
        return "before_25"
    elif normalized_name < q50:
        return "between_25_50"
    elif normalized_name < q75:
        return "between_50_75"
    else:
        return "after_75"

