#Creating A Function Called "checking_as_many_names"
def checking_as_many_names():
    #This Is Basically Creating A Variable, which stores names into a list
    names_list = []
    # This was my post-conditioned loop, which provides the user the chance to enter as many names as they want, but as soon as they type n, it quits them from the program (option b)
    while True:
        name = input ("Enter a name to check (N to quit): ")
        if name.lower() == "n":
            print("Goodbye! See You Next Time")
            break

        # Add the name to the list by appending it
        names_list.append(name)

        # Print the current list, and the quartile position for the name that was entered
        print(f"This is the current list: {names_list}")
        print(f"Quartile position for '{name}': {quartile_sort_position(name)}")


    # Print the list after the user quits
    print(f"Here Is The Final Display Of: {names_list}")
# Call your function
checking_as_many_names()
